autoresearch://schemas/experiment-spec:
{
  "$ref": "#/definitions/ExperimentSpec",
  "definitions": {
    "ExperimentSpec": {
      "type": "object",
      "properties": {
        "target_artifact": {
          "type": "string",
          "description": "What is being optimized (prompt, code file, config, etc.)"
        },
        "artifact_type": {
          "type": "string",
          "enum": [
            "prompt",
            "code",
            "config",
            "content",
            "other"
          ],
          "default": "other"
        },
        "technique": {
          "type": "object",
          "properties": {
            "search_strategy": {
              "type": "string",
              "enum": [
                "hill-climbing",
                "evolutionary",
                "bayesian-optimization",
                "beam-search",
                "multi-armed-bandit",
                "simulated-annealing",
                "ablation-elimination",
                "self-refine"
              ],
              "description": "How to explore the solution space"
            },
            "evaluator": {
              "type": "string",
              "enum": [
                "benchmark-harness",
                "binary-evaluator",
                "rubric-scorer",
                "llm-as-judge",
                "pairwise-comparison",
                "cost-latency-evaluator",
                "human-approval-gate",
                "regression-detector"
              ],
              "description": "How to measure results"
            },
            "execution_pattern": {
              "type": "string",
              "enum": [
                "single-ratchet",
                "two-loop",
                "bounded-episode",
                "branch-and-merge",
                "champion-challenger",
                "checkpoint-and-resume"
              ],
              "description": "How to orchestrate the loop"
            },
            "domain_template": {
              "type": "string",
              "enum": [
                "prompt-optimization",
                "code-performance",
                "config-tuning",
                "content-revision",
                "test-amplification",
                "ml-training",
                "literature-synthesis",
                "general-ratchet"
              ],
              "description": "Optional domain recipe for scaffolding"
            }
          },
          "required": [
            "search_strategy",
            "evaluator",
            "execution_pattern"
          ],
          "additionalProperties": false,
          "description": "Composed technique specification"
        },
        "recipe_id": {
          "type": "string",
          "enum": [
            "prompt-optimization",
            "code-performance",
            "config-tuning",
            "content-revision",
            "test-amplification",
            "ml-training",
            "literature-synthesis",
            "general-ratchet"
          ],
          "description": "Shorthand: use a predefined recipe"
        },
        "mutation_strategy": {
          "type": "string",
          "description": "How changes are proposed (LLM edit, random, evolutionary, etc.)"
        },
        "evaluator_command": {
          "type": "string",
          "description": "Command or script that returns a score (single float to stdout)"
        },
        "metric_name": {
          "type": "string",
          "description": "Name of the primary metric (e.g., val_bpb, test_pass_rate)"
        },
        "metric_direction": {
          "type": "string",
          "enum": [
            "minimize",
            "maximize"
          ],
          "default": "maximize"
        },
        "acceptance_rule": {
          "type": "string",
          "const": "strict-improvement",
          "default": "strict-improvement"
        },
        "budget": {
          "type": "object",
          "properties": {
            "max_iterations": {
              "type": "integer",
              "minimum": 0,
              "description": "Maximum experiment iterations"
            },
            "max_time_seconds": {
              "type": "number",
              "minimum": 0,
              "description": "Maximum wall-clock time"
            },
            "max_tokens": {
              "type": "integer",
              "minimum": 0,
              "description": "Maximum LLM tokens to spend"
            },
            "max_dollars": {
              "type": "number",
              "minimum": 0,
              "description": "Maximum dollar cost"
            }
          },
          "additionalProperties": false,
          "default": {}
        },
        "environment": {
          "type": "object",
          "properties": {
            "repo_sha": {
              "type": "string"
            },
            "dataset_version": {
              "type": "string"
            },
            "model_version": {
              "type": "string"
            },
            "dependency_lock": {
              "type": "string"
            }
          },
          "additionalProperties": false,
          "default": {}
        },
        "stopping_conditions": {
          "type": "array",
          "items": {
            "type": "string",
            "enum": [
              "max-iterations",
              "plateau",
              "convergence",
              "budget-exhaustion"
            ]
          },
          "default": [
            "budget-exhaustion"
          ]
        },
        "risk_policy": {
          "type": "object",
          "properties": {
            "sandbox_only": {
              "type": "boolean",
              "default": false,
              "description": "Must run in sandboxed environment"
            },
            "requires_approval": {
              "type": "boolean",
              "default": false,
              "description": "Human approval needed per iteration"
            },
            "network_denied": {
              "type": "boolean",
              "default": true,
              "description": "No network access during execution"
            },
            "secrets_denied": {
              "type": "boolean",
              "default": true,
              "description": "No access to env secrets"
            }
          },
          "additionalProperties": false,
          "default": {}
        },
        "constraints": {
          "type": "object",
          "properties": {
            "metric_floors": {
              "type": "object",
              "additionalProperties": {
                "type": "number"
              },
              "default": {},
              "description": "Minimum acceptable values for metrics"
            },
            "metric_ceilings": {
              "type": "object",
              "additionalProperties": {
                "type": "number"
              },
              "default": {},
              "description": "Maximum acceptable values for metrics"
            }
          },
          "additionalProperties": false,
          "default": {}
        }
      },
      "required": [
        "target_artifact",
        "mutation_strategy",
        "evaluator_command",
        "metric_name"
      ],
      "additionalProperties": false
    }
  },
  "$schema": "http://json-schema.org/draft-07/schema#"
}
